tool_input.command:
$env:PYTHONIOENCODING='utf-8'
Write-Output "== index.html 结构线索（targets/watch/候补/monitor 相关）=="
Select-String -Path '分析产出\持仓面板\index.html' -Pattern 'targets|PANEL_CONFIG|watch|候补|监控|MY_PORTFOLIO|renderRow|table|tbody' | Select-Object -First 25 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(100,$_.Line.Trim().Length)))"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== 银行专项/集中度常量 (final_portfolio_v3.py) =="
Select-String -Path '分析产出\final_portfolio_v3.py' -Pattern 'W_SINGLE_MAX|W_IND_MAX|BANK_HX_MIN|BANK_NPL_MAX|BANK_PROV_MIN|9\.5|1\.5|180' | Select-Object -First 12 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}
Write-Output "== screen_sh 阈值 TH =="
Select-String -Path '分析产出\screen_sh.py' -Pattern 'TH = dict|yld3_min|debt_max|pay_lo|pay_hi|ocfd_min|roe_min|ocf_np_min|ret12_min|np_cagr_min|div3_min|vol_max|amt_min|yld_ratio_max|vol_win|min_obs' | ForEach-Object {"$($_.Line.Trim())"}
Write-Output "== data_sufficiency 门槛 =="
Select-String -Path '分析产出\data_sufficiency.py' -Pattern '200|252|60|63|def ' | Select-Object -First 12 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== 深市标准 screen_sz 阈值/条件 =="
Select-String -Path '分析产出\screen_sz.py' -Pattern "TH\w*=|vol_max|yld|pay|ocfd|amt|治理|连续分红|def main|f'[①②③④⑤⑥⑦]" | Select-Object -First 25 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}
Write-Output "== 深市名单 7 条（从 md 或脚本打印）=="
Select-String -Path '分析产出\screen_sz.py' -Pattern '基础池|波动|分红|支付率|治理|最终入选' | Select-Object -First 12 | ForEach-Object {"$($_.Line.Trim())"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== screen_sz.py 是否涉及银行专项/核心一级 =="
Select-String -Path '分析产出\screen_sz.py' -Pattern 'HXYJBCZL|核心一级|bank_risk|不良|拨备|is_bank|银行专项' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}
Write-Output "== screen_sh.py 是否有银行专项门槛 =="
Select-String -Path '分析产出\screen_sh.py' -Pattern 'HXYJBCZL|核心一级|bank_risk|不良|拨备|银行专项' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== screen_sz 输出前最后几步（找银行过滤插入点）=="
Select-String -Path '分析产出\screen_sz.py' -Pattern '最终入选|入选 |to_csv|治理通过|gov|def main|OUT' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}
Write-Output ""
Write-Output "== screen_sh 输出前（银行专项应插在 11条后、输出前）=="
Select-String -Path '分析产出\screen_sh.py' -Pattern '11 条全过|to_csv|is_bank|银行|idx\[.④.\]' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}

